import java.util.*;
import java.util.function.LongSupplier;

public class Solution {
    static class KvStore {
        private static final long SEM_EXPIRACAO = Long.MAX_VALUE;

        private record Entrada(String valor, long expiraEm) {}
        private record Agendamento(long expiraEm, String chave) {}

        private final LongSupplier relogio;
        private final Map<String, Entrada> dados = new HashMap<>();
        // Heap de expirações: a próxima chave a vencer fica no topo.
        // Pode conter entradas obsoletas (chave sobrescrita ou apagada); elas são ignoradas na varredura.
        private final PriorityQueue<Agendamento> expiracoes =
                new PriorityQueue<>(Comparator.comparingLong(Agendamento::expiraEm));

        KvStore(LongSupplier relogio) {
            this.relogio = Objects.requireNonNull(relogio);
        }

        // O(1)
        void put(String chave, String valor) {
            validar(chave, valor);
            dados.put(chave, new Entrada(valor, SEM_EXPIRACAO));
        }

        // O(log n) por causa do heap
        void put(String chave, String valor, long ttlMillis) {
            validar(chave, valor);
            if (ttlMillis <= 0) throw new IllegalArgumentException("ttl deve ser positivo");
            long expiraEm = relogio.getAsLong() + ttlMillis;
            dados.put(chave, new Entrada(valor, expiraEm));
            expiracoes.add(new Agendamento(expiraEm, chave));
        }

        // O(1): expiração preguiçosa
        Optional<String> get(String chave) {
            Entrada e = viva(chave);
            return e == null ? Optional.empty() : Optional.of(e.valor());
        }

        boolean delete(String chave) {
            return viva(chave) != null && dados.remove(chave) != null;
        }

        long ttlRemaining(String chave) {
            Entrada e = viva(chave);
            if (e == null) return -2;
            if (e.expiraEm() == SEM_EXPIRACAO) return -1;
            return e.expiraEm() - relogio.getAsLong();
        }

        int size() {
            purgeExpired();
            return dados.size();
        }

        // O(k log n) para k agendamentos vencidos: só olha o topo do heap.
        int purgeExpired() {
            long agora = relogio.getAsLong();
            int removidas = 0;
            while (!expiracoes.isEmpty() && expiracoes.peek().expiraEm() <= agora) {
                Agendamento a = expiracoes.poll();
                Entrada atual = dados.get(a.chave());
                // Só remove se o agendamento ainda descreve a versão atual da chave.
                if (atual != null && atual.expiraEm() == a.expiraEm()) {
                    dados.remove(a.chave());
                    removidas++;
                }
            }
            return removidas;
        }

        private Entrada viva(String chave) {
            Entrada e = dados.get(chave);
            if (e == null) return null;
            if (e.expiraEm() <= relogio.getAsLong()) {
                dados.remove(chave);
                return null;
            }
            return e;
        }

        private static void validar(String chave, String valor) {
            if (chave == null || valor == null) throw new IllegalArgumentException("chave e valor obrigatorios");
        }
    }
}

