import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.time.Duration;
import java.util.Optional;

class SolutionTest {
    final long[] agora = {0};
    final Solution.KvStore kv = new Solution.KvStore(() -> agora[0]);

    @Test void putEGetSemTtl() {
        kv.put("a", "1");
        assertEquals(Optional.of("1"), kv.get("a"));
        assertEquals(Optional.empty(), kv.get("b"));
    }

    @Test void venceExatamenteNoInstanteDeExpiracao() {
        kv.put("sessao", "abc", 100);
        agora[0] = 99;
        assertEquals(Optional.of("abc"), kv.get("sessao"));
        agora[0] = 100;
        assertEquals(Optional.empty(), kv.get("sessao"));
    }

    @Test void putSemTtlRemoveExpiracaoAnterior() {
        kv.put("a", "1", 100);
        kv.put("a", "2");
        agora[0] = 10_000;
        assertEquals(Optional.of("2"), kv.get("a"));
        assertEquals(-1, kv.ttlRemaining("a"));
    }

    @Test void expiracaoAntigaNaoApagaValorNovo() {
        kv.put("a", "1", 100);
        agora[0] = 50;
        kv.put("a", "2", 100); // agora expira em 150
        agora[0] = 120;
        assertEquals(0, kv.purgeExpired());
        assertEquals(Optional.of("2"), kv.get("a"));
        agora[0] = 150;
        assertEquals(1, kv.purgeExpired());
        assertEquals(Optional.empty(), kv.get("a"));
    }

    @Test void ttlRemaining() {
        assertEquals(-2, kv.ttlRemaining("x"));
        kv.put("p", "v");
        assertEquals(-1, kv.ttlRemaining("p"));
        kv.put("t", "v", 1_000);
        agora[0] = 400;
        assertEquals(600, kv.ttlRemaining("t"));
        agora[0] = 1_000;
        assertEquals(-2, kv.ttlRemaining("t"));
    }

    @Test void deleteSoContaChaveViva() {
        kv.put("a", "1");
        assertTrue(kv.delete("a"));
        assertFalse(kv.delete("a"));
        kv.put("b", "1", 10);
        agora[0] = 10;
        assertFalse(kv.delete("b"));
    }

    @Test void sizeContaSoChavesVivas() {
        kv.put("a", "1");
        kv.put("b", "1", 10);
        kv.put("c", "1", 20);
        assertEquals(3, kv.size());
        agora[0] = 15;
        assertEquals(2, kv.size());
    }

    @Test void purgeNaoContaChaveJaRemovidaPeloGet() {
        kv.put("a", "1", 10);
        kv.put("b", "1", 10);
        agora[0] = 10;
        assertEquals(Optional.empty(), kv.get("a"));
        assertEquals(1, kv.purgeExpired());
    }

    @Test void entradasInvalidas() {
        assertThrows(IllegalArgumentException.class, () -> kv.put("a", "1", 0));
        assertThrows(IllegalArgumentException.class, () -> kv.put("a", "1", -5));
        assertThrows(IllegalArgumentException.class, () -> kv.put(null, "1"));
        assertThrows(IllegalArgumentException.class, () -> kv.put("a", null, 10));
    }

    @Test void purgeEmMassaNaoVarreTudo() {
        assertTimeout(Duration.ofSeconds(3), () -> {
            for (int i = 0; i < 100_000; i++) kv.put("k" + i, "v", i % 1000 + 1);
            agora[0] = 500;
            assertEquals(50_000, kv.purgeExpired());
            assertEquals(50_000, kv.size());
            for (int i = 0; i < 2_000; i++) {
                agora[0]++;
                kv.purgeExpired();
            }
            assertEquals(0, kv.size());
        });
    }
}
